<?php require_once __DIR__.'/document_studio_common.php';uid();try{$pid=trim((string)($_GET['project_id']??''));project($pdo,$pid);$q=$pdo->prepare('SELECT * FROM document_types WHERE is_active=1 AND(project_id IS NULL OR project_id=?) ORDER BY is_chapter DESC,is_requirement DESC,name');$q->execute([$pid]);out(['success'=>true,'types'=>$q->fetchAll(PDO::FETCH_ASSOC)]);}catch(Throwable$e){out(['success'=>false,'error'=>$e->getMessage()],500);}